	wire [8:0] env_int_p0;
	reg [8:0] env_int_pre_p2;
	reg [8:0] eg_inc_p2;
	reg eg_off_p2;
	reg [11:0] env_int_extra_bits_p2;
	reg [8:0] env_int_new_p3 = 0;
