module mem_multi_bank (
	clk,
	wea,
	reb,
	banka,
	addra,
	bankb,
	addrb,
	dia,
	dob
);
	reg _sv2v_0;
	parameter DATA_WIDTH = 0;
	parameter DEPTH = 0;
	parameter OUTPUT_DELAY = 0;
	parameter DEFAULT_VALUE = 0;
	parameter NUM_BANKS = 0;
	parameter BANK_WIDTH = `CLOG2(NUM_BANKS);
	parameter SYNC = 0;
	parameter LOGIC = 0;
	input wire clk;
	input wire wea;
	input wire reb;
	input wire [BANK_WIDTH - 1:0] banka;
	input wire [`CLOG2(DEPTH) - 1:0] addra;
	input wire [BANK_WIDTH - 1:0] bankb;
	input wire [`CLOG2(DEPTH) - 1:0] addrb;
	input wire [DATA_WIDTH - 1:0] dia;
	output reg [DATA_WIDTH - 1:0] dob;
	localparam AW = `CLOG2(DEPTH);
	localparam WORDS = NUM_BANKS << AW;
	localparam [DATA_WIDTH - 1:0] DEF = DEFAULT_VALUE;
	wire [(BANK_WIDTH + AW) - 1:0] wa = {banka, addra};
	wire [(BANK_WIDTH + AW) - 1:0] ra = {bankb, addrb};
	reg [DATA_WIDTH - 1:0] q;
	reg [DATA_WIDTH - 1:0] dob_p1 = DEF;
	reg [DATA_WIDTH - 1:0] dob_p2 = DEF;
	generate
		if (LOGIC || ((OUTPUT_DELAY == 0) && !SYNC)) begin : regs
			(* ramstyle = "logic" *) reg [DATA_WIDTH - 1:0] ram [0:WORDS - 1];
			initial begin : sv2v_autoblock_1
				reg signed [31:0] k;
				for (k = 0; k < WORDS; k = k + 1)
					ram[k] = DEF;
			end
			always @(posedge clk)
				if (wea)
					ram[wa] <= dia;
			if ((OUTPUT_DELAY == 0) && SYNC) begin : genblk1
				reg [DATA_WIDTH - 1:0] q_r = DEF;
				always @(posedge clk) q_r <= ram[ra];
				always @(*) begin
					if (_sv2v_0)
						;
					q = q_r;
				end
			end
			else begin : genblk1
				always @(*) begin
					if (_sv2v_0)
						;
					q = ram[ra];
				end
			end
			if (OUTPUT_DELAY != 0) begin : genblk2
				always @(posedge clk)
					if (reb)
						dob_p1 <= ram[ra];
			end
		end
		else begin : m9k
			(* ramstyle = "M9K" *) reg [DATA_WIDTH - 1:0] ram [0:WORDS - 1];
			initial begin : sv2v_autoblock_2
				reg signed [31:0] k;
				for (k = 0; k < WORDS; k = k + 1)
					ram[k] = DEF;
			end
			always @(posedge clk)
				if (wea)
					ram[wa] <= dia;
			if (OUTPUT_DELAY == 0) begin : genblk1
				reg [DATA_WIDTH - 1:0] q_r;
				always @(posedge clk) q_r <= ram[ra];
				always @(*) begin
					if (_sv2v_0)
						;
					q = q_r;
				end
			end
			else begin : genblk1
				always @(*) begin
					if (_sv2v_0)
						;
					q = 1'sb0;
				end
				always @(posedge clk)
					if (reb)
						dob_p1 <= ram[ra];
			end
		end
	endgenerate
	always @(posedge clk) dob_p2 <= dob_p1;
	always @(*) begin
		if (_sv2v_0)
			;
		if (OUTPUT_DELAY == 0)
			dob = q;
		else if (OUTPUT_DELAY == 1)
			dob = dob_p1;
		else
			dob = dob_p2;
	end
	initial _sv2v_0 = 0;
endmodule
