module opl3_ram_be (
	clk,
	be,
	wa,
	wd,
	ra,
	q
);
	parameter LANES = 4;
	parameter AW = 6;
	input wire clk;
	input wire [LANES - 1:0] be;
	input wire [AW - 1:0] wa;
	input wire [(LANES * 8) - 1:0] wd;
	input wire [AW - 1:0] ra;
	output wire [(LANES * 8) - 1:0] q;
	genvar _gv_l_1;
	generate
		for (_gv_l_1 = 0; _gv_l_1 < LANES; _gv_l_1 = _gv_l_1 + 1) begin : lane
			localparam l = _gv_l_1;
			reg [7:0] ram [0:(2 ** AW) - 1];
			reg [7:0] q_l;
			always @(posedge clk) begin
				if (be[l])
					ram[wa] <= wd[l * 8+:8];
				q_l <= ram[ra];
			end
			assign q[l * 8+:8] = q_l;
		end
	endgenerate
endmodule
