	pipeline_sr #(.ENDING_CYCLE(PIPELINE_DELAY)) sample_clk_en_sr(
		.clk(clk),
		.in(sample_clk_en),
		.out(sample_clk_en_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(opl3_pkg_BANK_NUM_WIDTH),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) bank_num_sr(
		.clk(clk),
		.in(bank_num),
		.out(bank_num_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(opl3_pkg_OP_NUM_WIDTH),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) op_num_sr(
		.clk(clk),
		.in(op_num),
		.out(op_num_p)
	);
	always @(*) begin
		if (_sv2v_0)
			;
		op_type_p0 = 3'd0;
		key_on_p0 = kon;
		if ((bank_num == 0) && ryt)
			(* full_case, parallel_case *)
			case (op_num)
				12, 15: begin
					op_type_p0 = 3'd1;
					key_on_p0 = kon || bd;
				end
				13: begin
					op_type_p0 = 3'd2;
					key_on_p0 = kon || hh;
				end
				14: begin
					op_type_p0 = 3'd3;
					key_on_p0 = kon || tom;
				end
				16: begin
					op_type_p0 = 3'd4;
					key_on_p0 = kon || sd;
				end
				17: begin
					op_type_p0 = 3'd5;
					key_on_p0 = kon || tc;
				end
				default:
					;
			endcase
	end
	calc_phase_inc calc_phase_inc(
		.clk(clk),
		.sample_clk_en(sample_clk_en),
		.bank_num(bank_num),
		.op_num(op_num),
		.fnum(fnum),
		.mult(mult),
		.block(block),
		.vib(vib),
		.dvb(dvb),
		.phase_inc_p2(phase_inc_p2)
	);
	envelope_generator envelope_generator(
		.clk(clk),
		.reset(reset),
		.sample_clk_en(sample_clk_en),
		.bank_num(bank_num),
		.op_num(op_num),
		.ar(ar),
		.dr(dr),
		.sl(sl),
		.rr(rr),
		.tl(tl),
		.ksr(ksr),
		.ksl(ksl),
		.egt(egt),
		.am(am),
		.dam(dam),
		.nts(nts),
		.fnum(fnum),
		.mult(mult),
		.block(block),
		.key_on_p0(key_on_p0),
		.env_p3(env_p3),
		.pg_reset_p2(pg_reset_p2)
	);
	phase_generator phase_generator(
		.modulation_p1((use_feedback_p1 ? feedback_result_p1 : modulation_p1)),
		.clk(clk),
		.sample_clk_en(sample_clk_en),
		.is_new(is_new),
		.bank_num(bank_num),
		.op_num(op_num),
		.phase_inc_p2(phase_inc_p2),
		.ws(ws),
		.env_p3(env_p3),
		.pg_reset_p2(pg_reset_p2),
		.op_type_p0(op_type_p0),
		.out_p6(out_p6)
	);
	always @(*) begin
		if (_sv2v_0)
			;
		feedback_p6[0+:13] = out_p6;
		feedback_p6[13+:13] = feedback_p[156+:13];
	end
	mem_multi_bank #(
		.DATA_WIDTH(26),
		.DEPTH(opl3_pkg_NUM_OPERATORS_PER_BANK),
		.OUTPUT_DELAY(1),
		.DEFAULT_VALUE(0),
		.NUM_BANKS(opl3_pkg_NUM_BANKS)
	) feedback_mem(
		.clk(clk),
		.wea(sample_clk_en_p[6]),
		.reb(sample_clk_en),
		.banka(bank_num_p[6+:1]),
		.addra(op_num_p[30+:5]),
		.bankb(bank_num),
		.addrb(op_num),
		.dia(feedback_p6),
		.dob(feedback_p1)
	);
	pipeline_sr #(
		.DATA_WIDTH(26),
		.STARTING_CYCLE(2),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) feedback_sr(
		.clk(clk),
		.in(feedback_p1),
		.out(feedback_p)
	);
	always @(*) begin
		if (_sv2v_0)
			;
		feedback_result_tmp_p1 = (fb_p1 == 0 ? 0 : ($signed(feedback_p1[0+:13]) + $signed(feedback_p1[13+:13])) <<< fb_p1);
		feedback_result_p1 = feedback_result_tmp_p1 >>> 9;
	end
	initial _sv2v_0 = 0;
endmodule
