module opl3_fm (
	clk,
	reset_a,
	wr_tgl,
	wr_word,
	tick_tgl,
	out_l,
	out_r
);
	input wire clk;
	input wire reset_a;
	input wire wr_tgl;
	input wire [16:0] wr_word;
	input wire tick_tgl;
	output reg signed [19:0] out_l = 0;
	output reg signed [19:0] out_r = 0;
	reg [1:0] rst_s = 2'b11;
	wire reset;
	always @(posedge clk) rst_s <= {rst_s[0], reset_a};
	assign reset = rst_s[1];
	reg [2:0] wr_s = 0;
	reg [2:0] tick_s = 0;
	always @(posedge clk) begin
		wr_s <= {wr_s[1:0], wr_tgl};
		tick_s <= {tick_s[1:0], tick_tgl};
	end
	wire wr_ev = wr_s[2] ^ wr_s[1];
	wire tick_ev = tick_s[2] ^ tick_s[1];
	reg [9:0] init_cnt = 0;
	always @(posedge clk)
		if (reset)
			init_cnt <= 0;
		else if (!init_cnt[9])
			init_cnt <= init_cnt + 1'd1;
	wire [7:0] ia = init_cnt[7:0];
	wire [7:0] init_data = ((ia >= 8'h40) && (ia <= 8'h55) ? 8'h3f : ((ia >= 8'h80) && (ia <= 8'h95) ? 8'h0f : 8'h00));
	localparam opl3_pkg_REG_FILE_DATA_WIDTH = 8;
	reg [17:0] reg_wr;
	always @(posedge clk) begin
		reg_wr <= 0;
		if (!init_cnt[9] && !reset) begin
			reg_wr[17] <= 1;
			reg_wr[16] <= init_cnt[8];
			reg_wr[15-:8] <= ia;
			reg_wr[7-:opl3_pkg_REG_FILE_DATA_WIDTH] <= init_data;
		end
		else if (wr_ev && !reset) begin
			reg_wr[17] <= 1;
			reg_wr[16] <= wr_word[16];
			reg_wr[15-:8] <= wr_word[15:8];
			reg_wr[7-:opl3_pkg_REG_FILE_DATA_WIDTH] <= wr_word[7:0];
		end
	end
	wire acc_valid;
	wire signed [19:0] acc_l;
	wire signed [19:0] acc_r;
	channels channels(
		.clk(clk),
		.reset(reset),
		.opl3_reg_wr(reg_wr),
		.sample_clk_en(tick_ev && init_cnt[9]),
		.acc_valid(acc_valid),
		.acc_l(acc_l),
		.acc_r(acc_r)
	);
	always @(posedge clk)
		if (reset) begin
			out_l <= 0;
			out_r <= 0;
		end
		else if (acc_valid) begin
			out_l <= acc_l;
			out_r <= acc_r;
		end
endmodule
