		.DATA_WIDTH(opl3_pkg_BANK_NUM_WIDTH),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) bank_num_sr(
		.clk(clk),
		.in(bank_num),
		.out(bank_num_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(opl3_pkg_OP_NUM_WIDTH),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) op_num_sr(
		.clk(clk),
		.in(op_num),
		.out(op_num_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(3),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) op_type_sr(
		.clk(clk),
		.in(op_type_p0),
		.out(op_type_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(opl3_pkg_OP_OUT_WIDTH),
		.STARTING_CYCLE(2),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) modulation_sr(
		.clk(clk),
		.in(modulation_p1),
		.out(modulation_p)
	);
	pipeline_sr #(
		.DATA_WIDTH(opl3_pkg_PHASE_FINAL_WIDTH),
		.STARTING_CYCLE(4),
		.ENDING_CYCLE(PIPELINE_DELAY)
	) final_phase_sr(
		.clk(clk),
		.in(final_phase_p3),
		.out(final_phase_p)
	);
