		if (_sv2v_0)
			;
		exp_out_post_level_p5 = ((exp_out_p5 | 'h400) << 1) >> (level_p5 >> 8);
	end
	always @(posedge clk) out_p6 <= exp_out_post_level_p5 ^ neg_p5;
	initial _sv2v_0 = 0;
