module tremolo (
	clk,
	sample_clk_en,
	bank_num,
	op_num,
	dam,
	am_val_p2
);
	reg _sv2v_0;
	input wire clk;
	input wire sample_clk_en;
	localparam opl3_pkg_NUM_BANKS = 2;
	localparam opl3_pkg_BANK_NUM_WIDTH = 1;
	input wire [0:0] bank_num;
	localparam opl3_pkg_NUM_OPERATORS_PER_BANK = 18;
	localparam opl3_pkg_OP_NUM_WIDTH = 5;
	input wire [4:0] op_num;
	input wire dam;
	localparam opl3_pkg_TREMOLO_MAX_COUNT = 13312;
	localparam opl3_pkg_TREMOLO_INDEX_WIDTH = 14;
	localparam opl3_pkg_AM_VAL_WIDTH = 6;
	output reg [5:0] am_val_p2 = 0;
	localparam PIPELINE_DELAY = 2;
	reg [5:0] timer = 1;
	reg [7:0] pos = 0;
	reg [7:0] tri_v;
	reg [5:0] am_reg = 0;
	always @(*) begin
		if (_sv2v_0)
			;
		tri_v = (pos < 8'd105 ? pos : 8'd210 - pos);
	end
	reg [3:0] lfo_cnt = 0;
	reg lfo_upd;
	always @(posedge clk)
		if ((sample_clk_en && (bank_num == 1)) && (op_num == 17))
			lfo_cnt <= 1;
		else if (lfo_cnt != 0)
			lfo_cnt <= lfo_cnt + 1'd1;
	always @(*) begin
		if (_sv2v_0)
			;
		lfo_upd = lfo_cnt == 4'd15;
	end
	always @(posedge clk)
		if (lfo_upd) begin
			timer <= timer + 1'd1;
			am_reg <= (dam ? tri_v[7:2] : {2'd0, tri_v[7:4]});
			if (timer == 6'h3f)
				pos <= (pos == 8'd209 ? 8'd0 : pos + 1'd1);
		end
	always @(posedge clk) am_val_p2 <= am_reg;
	initial _sv2v_0 = 0;
endmodule
